  # Broadcasting is already handled by the caller (mfun)
  
  # Apply broadcasting preparation to S and T
  # This ensures S and T have compatible shapes for element-wise operations
  broadcast_result <- .prepare_broadcasting(S, T)
  S <- broadcast_result$s
  T <- broadcast_result$t
  
  # ORDER 2, 2D: Symbolic formula (ported from MATLAB estimated_lwp_estimator.m)
